package com.byawasaya.platform.auth;

import java.util.Map;
import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
import jakarta.validation.Valid; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size;

@RestController @RequestMapping("/api/auth")
public class AuthSecurityController {
 private final UserAccountRepository accounts; private final EmailActionService emailActions; private final PasswordEncoder encoder; private final TokenService sessions; private final PlatformUserRepository platformUsers; private final boolean cookieSecure; private final String sameSite; private final LoginRateLimitService rateLimit;
 public AuthSecurityController(UserAccountRepository accounts,EmailActionService emailActions,PasswordEncoder encoder,TokenService sessions,PlatformUserRepository platformUsers,@org.springframework.beans.factory.annotation.Value("${app.auth.cookie-secure:false}")boolean cookieSecure,@org.springframework.beans.factory.annotation.Value("${app.auth.cookie-same-site:Lax}")String sameSite,LoginRateLimitService rateLimit){this.accounts=accounts;this.emailActions=emailActions;this.encoder=encoder;this.sessions=sessions;this.platformUsers=platformUsers;this.cookieSecure=cookieSecure;this.sameSite=sameSite;this.rateLimit=rateLimit;}
 public record ChangePasswordRequest(@NotBlank String currentPassword,@NotBlank @Size(min=12,max=72) String newPassword){} public record VerifyRequest(@NotBlank String token){} public record ForgotRequest(@NotBlank @Email @Size(max=180) String email){} public record ResetRequest(@NotBlank String token,@NotBlank @Size(min=12,max=72) String password){}
 @PostMapping("/email/verification/confirm") public Map<String,String> verify(@Valid @RequestBody VerifyRequest r){try{emailActions.verifyEmail(r.token());return Map.of("message","Email verified. You can now submit your store application.");}catch(IllegalArgumentException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid or expired verification link.");}}
 @PostMapping("/email/verification/resend") public Map<String,String> resend(org.springframework.security.core.Authentication auth,jakarta.servlet.http.HttpServletRequest request){rateLimit.check("verification:"+auth.getName(),request.getRemoteAddr());rateLimit.failure("verification:"+auth.getName(),request.getRemoteAddr());accounts.findByUsernameIgnoreCase(auth.getName()).filter(a->!a.isEmailVerified()).ifPresent(emailActions::sendVerification);return Map.of("message","If your account needs verification, a new email has been sent.");}

 @PostMapping("/password/change") public Map<String,String> changePassword(@Valid @RequestBody ChangePasswordRequest r,org.springframework.security.core.Authentication auth,jakarta.servlet.http.HttpServletResponse response,@org.springframework.web.bind.annotation.CookieValue(name=BearerTokenFilter.COOKIE_NAME,required=false)String cookie){
  var platform=platformUsers.findByUsernameIgnoreCase(auth.getName());if(platform.isPresent()){PlatformUser u=platform.get();if(!encoder.matches(r.currentPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");u.setPasswordHash(encoder.encode(r.newPassword()));platformUsers.save(u);}else{UserAccount u=accounts.findByUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Account not found."));if(!encoder.matches(r.currentPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");u.setPasswordHash(encoder.encode(r.newPassword()));accounts.save(u);}
  sessions.revokeUser(auth.getName());sessions.revoke(cookie,"PASSWORD_CHANGED");response.addHeader("Set-Cookie",SessionCookieFactory.create(BearerTokenFilter.COOKIE_NAME,"",java.time.Duration.ZERO,cookieSecure,sameSite,"").toString());return Map.of("message","Password changed. All sessions were revoked; sign in again.");
 }
 @PostMapping("/password/forgot") public Map<String,String> forgot(@Valid @RequestBody ForgotRequest r,jakarta.servlet.http.HttpServletRequest request){String email=r.email().trim().toLowerCase();rateLimit.check("password-reset:"+email,request.getRemoteAddr());rateLimit.failure("password-reset:"+email,request.getRemoteAddr());accounts.findByUsernameIgnoreCase(email).ifPresent(a->{try{emailActions.sendPasswordReset(a);}catch(RuntimeException ignored){/* Same response regardless of account or mail status. */}});return Map.of("message","If an account matches that email, password-reset instructions will be sent.");}
 @PostMapping("/password/reset") public Map<String,String> reset(@Valid @RequestBody ResetRequest r,jakarta.servlet.http.HttpServletRequest request){rateLimit.check("password-reset-confirm",request.getRemoteAddr());try{emailActions.resetPassword(r.token(),r.password(),encoder,sessions);rateLimit.success("password-reset-confirm",request.getRemoteAddr());return Map.of("message","Password changed. Sign in again with the new password.");}catch(IllegalArgumentException ex){rateLimit.failure("password-reset-confirm",request.getRemoteAddr());throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid or expired password-reset link.");}}
}
